import { ethers, getProvider, sendTx } from './contracts.js';
import { CONTRACTS } from './chain-config.js';
import { get } from './store.js';
import { permissionlessReadProvider, readProviderBlockNumber } from './read-provider.js';
import { abi as GNRUS_ABI } from '../chain/generated/gnrus.js';
import { readClaimableCoinflip } from './coinflip.js';
import { flipFromChain, flipToChain } from './token-units.js';

const BALANCE_ABI = ['function balanceOf(address) view returns (uint256)'];
const GAME_ABI = ['function claimableWinningsOf(address) view returns (uint256)'];
export const MIN_GNRUS_REDEEM = 10n ** 18n;
let factory = null;
const contract = (address, abi, runner) => factory ? factory(address, abi, runner) : new ethers.Contract(address, abi, runner);
export function __setGnrusContractFactoryForTest(value) { factory = value; }
function reader() {
  const provider = permissionlessReadProvider(getProvider());
  if (!provider || !CONTRACTS.GNRUS) throw new Error('GNRUS is unavailable. Try again.');
  return provider;
}
export async function readGnrusBalance(player) {
  if (!ethers.isAddress(player)) return null;
  const provider = reader();
  const blockTag = await readProviderBlockNumber(provider);
  return BigInt(await contract(CONTRACTS.GNRUS, GNRUS_ABI, provider).balanceOf(player, { blockTag }));
}
export async function readGnrusRedemption(player) {
  if (!ethers.isAddress(player)) throw new Error('Connect your wallet first.');
  const provider = reader();
  const blockTag = await readProviderBlockNumber(provider);
  const gnrus = contract(CONTRACTS.GNRUS, GNRUS_ABI, provider);
  const [balance, supply, eth, steth, claimable] = await Promise.all([
    gnrus.balanceOf(player, { blockTag }), gnrus.totalSupply({ blockTag }),
    provider.getBalance(CONTRACTS.GNRUS, blockTag),
    contract(CONTRACTS.STETH_TOKEN, BALANCE_ABI, provider).balanceOf(CONTRACTS.GNRUS, { blockTag }),
    contract(CONTRACTS.GAME, GAME_ABI, provider).claimableWinningsOf(CONTRACTS.GNRUS, { blockTag }),
  ]);
  return { balance: BigInt(balance), supply: BigInt(supply),
    backing: BigInt(eth) + BigInt(steth) + (BigInt(claimable) > 1n ? BigInt(claimable) - 1n : 0n) };
}
export function gnrusRedemptionValue(state, amount) {
  if (!state || state.supply <= 0n) return 0n;
  return state.backing * BigInt(amount) / state.supply;
}
export async function redeemGnrus({ amount, expectedAccount } = {}) {
  let value;
  try { value = BigInt(amount); } catch { throw new Error('Enter a GNRUS amount.'); }
  if (value < MIN_GNRUS_REDEEM) throw new Error('Minimum redemption is 1 GNRUS.');
  const owner = String(expectedAccount || '').toLowerCase();
  if (!ethers.isAddress(owner)) throw new Error('Connect your wallet first.');
  return sendTx(async signer => {
    if (String(get('connected.address') || '').toLowerCase() !== owner
      || String(await signer.getAddress()).toLowerCase() !== owner) {
      throw new Error('Wallet changed. Reopen Redeem and try again.');
    }
    const gnrus = contract(CONTRACTS.GNRUS, GNRUS_ABI, signer);
    if (BigInt(await gnrus.balanceOf(owner)) < value) throw new Error('Not enough GNRUS.');
    return gnrus.burn(value);
  }, 'Redeem GNRUS');
}

// Donations. GNRUS's game account (ID 3) accepts ticket purchases from anyone, paid in fresh
// ETH exactly (DirectEth, no box, no foil; GamePurchase._purchase). Donated FLIP is a plain
// transfer to the GNRUS contract, which spends its wallet FLIP on tickets at purchase-phase end.
export const GNRUS_WALLET_ID = 3;
const TICKET_UNITS = 400n;
const DONATE_GAME_ABI = [
  'function purchaseOrderFor(uint32 id, uint256 entryQuantityScaled, uint256 boxOrder, bytes32 affiliateCode, uint8 payKind, bool foil) payable',
  'error E()',
];
const FLIP_ABI = [
  'function balanceOf(address) view returns (uint256)',
  'function transfer(address to, uint256 amount) returns (bool)',
];

/** ETH (wei) a donation of `tickets` whole tickets costs at `priceWei`. */
export function gnrusTicketDonationCost(priceWei, tickets) {
  // GamePurchase._purchaseCostInputs: priceWei * units / (4 * QTY_SCALE), 400 units per ticket.
  return (BigInt(priceWei) * BigInt(tickets) * TICKET_UNITS) / TICKET_UNITS;
}

/** Wallet FLIP plus settled coinflip winnings (the transfer claims the shortfall), in token wei. */
export async function readGnrusFlipDonationBalance(player) {
  if (!ethers.isAddress(player)) throw new Error('Connect your wallet first.');
  const provider = reader();
  const blockTag = await readProviderBlockNumber(provider);
  const [wallet, claimable] = await Promise.all([
    contract(CONTRACTS.COIN, FLIP_ABI, provider).balanceOf(player, { blockTag }),
    readClaimableCoinflip({ player }),
  ]);
  return flipFromChain(wallet) + (claimable == null ? 0n : BigInt(claimable));
}

function ownerSigner(expectedAccount) {
  const owner = String(expectedAccount || '').toLowerCase();
  if (!ethers.isAddress(owner)) throw new Error('Connect your wallet first.');
  return async signer => {
    if (String(get('connected.address') || '').toLowerCase() !== owner
      || String(await signer.getAddress()).toLowerCase() !== owner) {
      throw new Error('Wallet changed. Reopen Donate and try again.');
    }
  };
}

export async function donateGnrusTickets({ tickets, priceWei, expectedAccount } = {}) {
  let count;
  try { count = BigInt(tickets); } catch { throw new Error('Enter a whole ticket amount.'); }
  if (count <= 0n) throw new Error('Enter a whole ticket amount.');
  const price = BigInt(priceWei ?? 0);
  if (price <= 0n) throw new Error('Ticket price unavailable. Reopen to retry.');
  const check = ownerSigner(expectedAccount);
  const value = gnrusTicketDonationCost(price, count);
  return sendTx(async signer => {
    await check(signer);
    return contract(CONTRACTS.GAME, DONATE_GAME_ABI, signer).purchaseOrderFor(
      GNRUS_WALLET_ID, count * TICKET_UNITS, 0n, ethers.ZeroHash, 0, false, { value },
    );
  }, 'Donate tickets to GNRUS');
}

export async function donateGnrusFlip({ amount, expectedAccount } = {}) {
  let value;
  try { value = BigInt(amount); } catch { throw new Error('Enter a FLIP amount.'); }
  const raw = flipToChain(value);
  if (raw <= 0n) throw new Error('Enter a FLIP amount.');
  if (!CONTRACTS.COIN || !CONTRACTS.GNRUS) throw new Error('GNRUS is unavailable. Try again.');
  const check = ownerSigner(expectedAccount);
  return sendTx(async signer => {
    await check(signer);
    return contract(CONTRACTS.COIN, FLIP_ABI, signer).transfer(CONTRACTS.GNRUS, raw);
  }, 'Donate FLIP to GNRUS');
}
